import React, { useState } from 'react';
import axios from 'axios';

const Weather = () => {
    const [location, setLocation] = useState('');
    const [weatherData, setWeatherData] = useState(null);
    const [displayLocation, setDisplayLocation] = useState('');
    const api_key = process.env.REACT_APP_API_KEY;

    const fetchData = async () => {
        try {
            // Step 1: Convert location (postcode, town, or city) to coordinates
            const geoResponse = await axios.get(
                `https://api.openweathermap.org/geo/1.0/direct?q=${location}&limit=1&appid=${api_key}`
            );

            if (!geoResponse.data.length) {
                alert("Location not found.");
                return;
            }

            const { lat, lon, name, country, state } = geoResponse.data[0];

            // Step 2: Fetch weather data using coordinates
            const weatherResponse = await axios.get(
                `https://api.openweathermap.org/data/2.5/weather?lat=${lat}&lon=${lon}&units=metric&appid=${api_key}`
            );
            setWeatherData(weatherResponse.data);

            // Step 3: Reverse Geocoding to determine correct display location
            const reverseGeoResponse = await axios.get(
                `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lon}&format=json`
            );

            const address = reverseGeoResponse.data.address;

            // Determine what to display based on input type
            const formattedLocation =
                address.postcode ? address.postcode :
                address.city ? address.city :
                address.town ? address.town :
                address.village ? address.village :
                address.state ? address.state :
                name; // Default to OpenWeatherMap's name

            setDisplayLocation(`${formattedLocation}, ${country}`);

        } catch (error) {
            console.error(error);
        }
    };

    const handleInputChange = (e) => {
        setLocation(e.target.value);
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        fetchData();
    };

    return (
        <div>
            <form onSubmit={handleSubmit}>
                <input
                    type="text"
                    placeholder="Enter town, city, or postcode"
                    value={location}
                    onChange={handleInputChange}
                />
                <button type="submit">Get Weather</button>
            </form>
            {weatherData ? (
                <>
                    <h2>{displayLocation}</h2>
                    <p>Temperature: {weatherData.main.temp}°C</p>
                    <p>Description: {weatherData.weather[0].description}</p>
                </>
            ) : (
                <p>Enter a location to get weather.</p>
            )}
        </div>
    );
};

export default Weather;
